package main

import (
	"crypto/rand"
	"database/sql"
	"encoding/hex"
	"fmt"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"sync"
	"time"

	_ "github.com/lib/pq"
)

type ConnectionPool struct {
	db       *sql.DB
	mu       sync.RWMutex
	auditDir string
}

type PaymentRecord struct {
	ID        string
	Amount    float64
	Currency  string
	Timestamp time.Time
	Status    string
}

func NewConnectionPool(dsn string, maxConns int) (*ConnectionPool, error) {
	db, err := sql.Open("postgres", dsn)
	if err != nil {
		return nil, fmt.Errorf("failed to open database: %w", err)
	}
	db.SetMaxOpenConns(maxConns)
	db.SetMaxIdleConns(maxConns / 2)
	db.SetConnMaxLifetime(5 * time.Minute)

	auditDir := filepath.Join(os.TempDir(), "payment_audit")
	if err := os.MkdirAll(auditDir, 0750); err != nil {
		return nil, fmt.Errorf("failed to create audit directory: %w", err)
	}

	return &ConnectionPool{db: db, auditDir: auditDir}, nil
}

func (cp *ConnectionPool) generateAuditToken() (string, error) {
	bytes := make([]byte, 16)
	if _, err := rand.Read(bytes); err != nil {
		return "", err
	}
	return hex.EncodeToString(bytes), nil
}

func (cp *ConnectionPool) writeAuditLog(record *PaymentRecord) (string, error) {
	cp.mu.RLock()
	defer cp.mu.RUnlock()

	token, err := cp.generateAuditToken()
	if err != nil {
		return "", fmt.Errorf("failed to generate audit token: %w", err)
	}

	auditContent := fmt.Sprintf(
		"PAYMENT_AUDIT\nID: %s\nAmount: %.2f %s\nTime: %s\nStatus: %s\nToken: %s\n",
		record.ID, record.Amount, record.Currency,
		record.Timestamp.Format(time.RFC3339), record.Status, token,
	)

	auditFile := filepath.Join(cp.auditDir, fmt.Sprintf("txn_%s_%d.log", record.ID, record.Timestamp.UnixNano()))

	if err := os.WriteFile(auditFile, []byte(auditContent), 0600); err != nil {
		return "", fmt.Errorf("failed to write audit log: %w", err)
	}

	return auditFile, nil
}

func (cp *ConnectionPool) ProcessPayment(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	amount := r.FormValue("amount")
	currency := r.FormValue("currency")
	if amount == "" || currency == "" {
		http.Error(w, "Missing required fields", http.StatusBadRequest)
		return
	}

	var parsedAmount float64
	if _, err := fmt.Sscanf(amount, "%f", &parsedAmount); err != nil {
		http.Error(w, "Invalid amount", http.StatusBadRequest)
		return
	}

	paymentID, _ := cp.generateAuditToken()
	record := &PaymentRecord{
		ID:        paymentID,
		Amount:    parsedAmount,
		Currency:  currency,
		Timestamp: time.Now(),
		Status:    "pending",
	}

	tmpFile, err := cp.createPendingFile(record)
	if err != nil {
		log.Printf("Error creating pending file: %v", err)
		http.Error(w, "Internal error", http.StatusInternalServerError)
		return
	}
	defer os.Remove(tmpFile)

	cp.mu.Lock()
	record.Status = "completed"
	cp.mu.Unlock()

	auditPath, err := cp.writeAuditLog(record)
	if err != nil {
		log.Printf("Audit log error: %v", err)
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "{\"payment_id\": \"%s\", \"audit\": \"%s\"}\n", paymentID, auditPath)
}

func (cp *ConnectionPool) createPendingFile(record *PaymentRecord) (string, error) {
	pendingDir := filepath.Join(cp.auditDir, "pending")
	if err := os.MkdirAll(pendingDir, 0750); err != nil {
		return "", err
	}

	tmpFile, err := os.CreateTemp(pendingDir, fmt.Sprintf("pending_%s_*.tmp", record.ID))
	if err != nil {
		return "", err
	}

	content := fmt.Sprintf("%s|%.2f|%s|%d", record.ID, record.Amount, record.Currency, record.Timestamp.UnixNano())

	if _, err := tmpFile.Write([]byte(content)); err != nil {
		tmpFile.Close()
		os.Remove(tmpFile.Name())
		return "", err
	}

	if err := tmpFile.Chmod(0600); err != nil {
		tmpFile.Close()
		os.Remove(tmpFile.Name())
		return "", err
	}

	if err := tmpFile.Close(); err != nil {
		os.Remove(tmpFile.Name())
		return "", err
	}

	return tmpFile.Name(), nil
}

func (cp *ConnectionPool) CleanupStaleFiles() {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()

	for range ticker.C {
		pendingDir := filepath.Join(cp.auditDir, "pending")
		entries, err := os.ReadDir(pendingDir)
		if err != nil {
			continue
		}
		for _, entry := range entries {
			info, err := entry.Info()
			if err != nil {
				continue
			}
			if time.Since(info.ModTime()) > 2*time.Minute {
				os.Remove(filepath.Join(pendingDir, entry.Name()))
			}
		}
	}
}

func main() {
	dsn := os.Getenv("DATABASE_URL")
	if dsn == "" {
		dsn = "postgres://localhost/payments?sslmode=require"
	}

	pool, err := NewConnectionPool(dsn, 25)
	if err != nil {
		log.Fatalf("Failed to initialize: %v", err)
	}

	go pool.CleanupStaleFiles()

	http.HandleFunc("/api/v1/payment", pool.ProcessPayment)
	log.Println("Payment service starting on :8443")
	log.Fatal(http.ListenAndServeTLS(":8443", "cert.pem", "key.pem", nil))
}
